@namespace sv_3b9c47280fdc43db8362bbc4976ef173.Components.Pages.Settings

<div class="change-password-panel">
    <button class="btn btn-outline-secondary mb-3 d-flex align-items-center gap-2"
            @onclick="() => _expanded = !_expanded">
        <span class="expand-icon">@(_expanded ? "▾" : "▸")</span>
        Change Password
    </button>

    @if (_expanded)
    {
        <div class="card">
            <div class="card-body">
                @if (!string.IsNullOrEmpty(_message))
                {
                    <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                        @_message
                        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                    </div>
                }

                <div class="mb-3">
                    <label class="form-label fw-semibold">Current Password</label>
                    <input type="password" class="form-control" @bind="_currentPassword" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">New Password</label>
                    <input type="password" class="form-control" @bind="_newPassword" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Confirm New Password</label>
                    <input type="password" class="form-control @(_confirmMismatch ? "is-invalid" : "")"
                           @bind="_confirmPassword" />
                    @if (_confirmMismatch)
                    {
                        <div class="invalid-feedback">Passwords do not match.</div>
                    }
                </div>

                <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Update Password
                </button>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _saving;
    private string? _message;
    private bool _isError;
    private bool _confirmMismatch;

    private async Task UpdatePasswordAsync()
    {
        _message = null;
        _confirmMismatch = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _message = "Please fill in all password fields.";
            _isError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _confirmMismatch = true;
            return;
        }

        _saving = true;
        try
        {
            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
            _message = "Password updated successfully!";
            _isError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _message = $"Failed to update password: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }
}

