@namespace sv_3b9c47280fdc43db8362bbc4976ef173.Components.Pages.Settings
@using sv_3b9c47280fdc43db8362bbc4976ef173.Models
@inject ISettingsService SettingsService

<div class="security-section">
    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <h4 class="section-heading">Security</h4>
        <p class="text-muted mb-4">Manage your account security and active sessions.</p>

        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <hr />

        <div class="card mb-4">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="fw-semibold mb-1">Two-Factor Authentication</h6>
                        <small class="text-muted">Add an extra layer of security to your account.</small>
                    </div>
                    <div class="d-flex align-items-center gap-2">
                        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                        <div class="form-check form-switch mb-0">
                            <input class="form-check-input" type="checkbox" id="twoFactorToggle"
                                   checked="@_twoFactorEnabled"
                                   @onchange="Toggle2FA" />
                        </div>
                    </div>
                </div>
                @if (_settings?.LastPasswordChange is not null)
                {
                    <small class="text-muted d-block mt-2">
                        Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                    </small>
                }
            </div>
        </div>

        <h5 class="fw-semibold">Active Sessions</h5>
        <p class="text-muted small">These devices are currently signed into your account. The first session is your current one.</p>

        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @if (_sessions is not null)
                    {
                        @for (var i = 0; i < _sessions.Count; i++)
                        {
                            var session = _sessions[i];
                            var isCurrent = i == 0;
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-info ms-2">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td class="text-end">
                                    @if (!isCurrent)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>
        </div>

        <RevokeSessionDialog @ref="_revokeDialog"
                             Device="@(_sessionToRevoke?.Device ?? "")"
                             Location="@(_sessionToRevoke?.Location ?? "")"
                             OnConfirm="ConfirmRevoke"
                             OnCancel="CancelRevoke" />
    }
</div>

@code {
    private bool _loading = true;
    private SecuritySettings? _settings;
    private List<ActiveSession>? _sessions;
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private RevokeSessionDialog? _revokeDialog;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _sessions = _settings.Sessions.ToList();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _loading = false;
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private void Toggle2FA(ChangeEventArgs e)
    {
        _twoFactorEnabled = (bool)(e.Value ?? false);
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _revokeDialog?.Show();
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions?.RemoveAll(s => s.Id == _sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

.security-section .section-heading {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

@namespace sv_3b9c47280fdc43db8362bbc4976ef173.Components.Pages.Settings
@using sv_3b9c47280fdc43db8362bbc4976ef173.Models
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <h4 class="section-heading">Appearance</h4>
        <p class="text-muted mb-4">Customize how the application looks and feels.</p>

        @if (!string.IsNullOrEmpty(_statusMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_statusMessage
                <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-7">
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="fw-semibold mb-3">Theme</h6>
                        @foreach (var theme in _themes)
                        {
                            <div class="form-check mb-2">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="fw-semibold mb-3">Font Size</h6>
                        @foreach (var size in _fontSizes)
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="fw-semibold mb-3">Language</h6>
                        <select class="form-select" @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label fw-semibold" for="compactMode">
                                Compact Mode
                                <small class="d-block text-muted fw-normal">Reduce spacing and padding for a denser layout.</small>
                            </label>
                        </div>
                    </div>
                </div>
            </div>

            <div class="col-md-5">
                <div class="card">
                    <div class="card-header fw-semibold">Live Preview</div>
                    <div class="card-body preview-area @GetPreviewClasses()">
                        <h6 class="preview-heading">Sample Heading</h6>
                        <p class="preview-text">
                            This is how your content will look with the selected appearance settings.
                        </p>
                        <div class="preview-controls">
                            <button class="btn btn-sm btn-primary me-1">Primary</button>
                            <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                        </div>
                        <div class="preview-meta mt-2">
                            <small>Theme: @_theme · Font: @_fontSize · Lang: @_language · Compact: @(_compactMode ? "On" : "Off")</small>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <hr />

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save
        </button>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _statusMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();

        classes.Add(_theme switch
        {
            "Dark" => "preview-dark",
            _ => "preview-light"
        });

        classes.Add(_fontSize switch
        {
            "Small" => "preview-font-sm",
            "Large" => "preview-font-lg",
            _ => "preview-font-md"
        });

        if (_compactMode)
            classes.Add("preview-compact");

        return string.Join(" ", classes);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _statusMessage = "Appearance settings saved!";
        _saving = false;
    }
}

.appearance-section .section-heading {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

/* Live preview styles */
.preview-area {
    transition: all 0.2s ease;
