                        <div class="form-check form-switch mb-0">
                            <input class="form-check-input" type="checkbox" id="twoFactorToggle"
                                   checked="@_twoFactorEnabled"
                                   @onchange="Toggle2FA" />
                        </div>
                    </div>
                </div>
                @if (_settings?.LastPasswordChange is not null)
                {
                    <small class="text-muted d-block mt-2">
                        Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                    </small>
                }
            </div>
        </div>

        <h5 class="fw-semibold">Active Sessions</h5>
        <p class="text-muted small">These devices are currently signed into your account. The first session is your current one.</p>

